pub fn event_window_closed() {
    let mut h = Harness::new();
    let w = h.create("window");
    h.call(w, "activate", &[]).unwrap();
    h.listen(w, "closed", true).unwrap();
    h.call(w, "close", &[]).unwrap();
    h.pump(200);
    assert_eq!(h.events(w, "closed"), 1, "close while listened is vetoed and posted");
    assert!(h.gone(w).is_none(), "vetoed window stays alive");
    h.listen(w, "closed", false).unwrap();
    h.call(w, "close", &[]).unwrap();
    h.pump(200);
    assert_eq!(h.gone(w), Some(svelters_abi::SVL_GONE_CLOSED));
}

